}

/// `/tools [enable|disable <id> [global|project|session]|reload]`.
///
/// Dispatch only — each branch body lives in its own CC≤2 helper (the
/// `/skills` pattern).
Future<void> _toolsSlash(String rest) async {
  final (sub, parts) = splitSlashArgs(rest);
  switch (sub) {
    case '':
      _toolsList();
    case 'reload':
      await rebuildToolAvailability();
      io.writeln('tools: availability reloaded');
    case 'enable' || 'disable':
      await _toolsToggleSlash(sub == 'enable', parts);
    default:
      io.writeln(
        'unknown /tools subcommand: $sub (try enable, disable, reload)',
      );
  }
}

/// The `/tools` listing: one line per known id with its approval tier,
/// on/off state, deciding scope, and (when off) the reason.
void _toolsList() {
  final resolution = _toolGate.resolution;
  if (resolution == null) {
    io.writeln('tools: availability still loading — try /tools reload');
    return;
  }
  io.writeln('tool             tier   state scope    reason');
  for (final id in knownToolIds) {
    io.writeln(_toolsListLine(id, resolution.byId[id]!));
  }
}

String _toolsListLine(String id, ResolvedToolAvailability availability) {
  final tools = _toolGroupsById[id] ?? const <AgentTool>[];
  final tier = tools.isEmpty ? '-' : tools.first.tier.name;
  return '${id.padRight(16)} ${tier.padRight(6)} '
          '${(availability.enabled ? 'on' : 'off').padRight(5)} '
          '${availability.scope.name.padRight(8)} ${availability.reason ?? ''}'
      .trimRight();
}

Future<void> _toolsToggleSlash(bool enable, List<String> parts) async {
  if (parts.length < 2) {
    io.writeln(
      'usage: /tools ${enable ? 'enable' : 'disable'} <id> '
      '[global|project|session]',
    );
    return;
  }
  await _applyToolsToggle(
    enable,
    parts[1],
    parts.length > 2 ? parts[2] : 'project',
  );
}

/// Persists the toggle to [scope], then re-resolves availability. A
/// failed/unwritable target leaves the live state untouched.
Future<void> _applyToolsToggle(bool enable, String id, String scope) async {

  final name = (splitAt < 0 ? rest : rest.substring(0, splitAt)).trim();
  final args = splitAt < 0 ? '' : rest.substring(splitAt).trim();
  return (name, args);
}

/// `/skills [reload|access [ask|granted|denied]|import]`.
///
/// Dispatch only — each branch body lives in its own CC≤2 helper so every
/// piece stays under the CRAP ratchet even where only the line-mode paths
/// are test-covered.
Future<void> _skillsSlash(String rest) async {
  final (sub, parts) = splitSlashArgs(rest);
  switch (sub) {
    case '':
      await _skillsListOrMenu();
    case 'reload':
      await _skillsReloadSlash();
    case 'access':
      await _skillsAccessEntry(parts);
    case 'import':
      await _importThirdPartySkills();
    default:
      io.writeln(
        'unknown /skills subcommand: $sub (try reload, access, import)',
      );
  }
}

/// The bare `/skills` branch: the plain text list (line mode manages via
/// `/skills access`; a TUI management menu is a follow-up).
Future<void> _skillsListOrMenu() async {
  _listSkills();
}

/// The `/skills reload` branch: re-scan skills + agent types and report.
Future<void> _skillsReloadSlash() async {
  await _reloadSkills();
  await _reloadAgents();
  io.writeln(
    'reloaded: ${_skills.length} skill(s), '
    '${_discoveredAgents.length} discovered agent type(s)',
  );
}

/// The `/skills access` entry: a bare interactive line-mode invocation
/// runs DETACHED — the sequential REPL loop awaits each command, so an
/// awaited line-prompted flow would deadlock on its own answer (guided
/// provider flows use the same pattern; answers arrive through
/// `_pendingPromptAnswer` from the loop's next reads).
Future<void> _skillsAccessEntry(List<String> parts) async {
  final bareInteractiveLine =
      parts.length == 1 &&
      io.isInteractive &&
      !(_useTui && _tuiController != null);
  if (bareInteractiveLine) {
    unawaited(_openSkillsAccessPicker());
    return;
  }
  await _skillsAccessSlash(parts.length > 1 ? parts[1] : '');
}

