  final buffer = StringBuffer()
    ..write('#### #${record.index} tool `${record.name}` `${record.callId}`')
    ..write(record.isError ? ' · ERROR\n' : '\n')
    ..write('arguments:\n')
    ..write(_mdFence(record.argsRaw, language: 'json'));
  if (record.result.isNotEmpty || record.isError) {
    buffer
